Example usage in the webhook authorizer (this comes later):
```go
func (WebhookAuthorizer) EvaluateConditions(unevaluatedDecision, data) (Decision, string, error) {
   celEnv := buildCELEnv(data)
   remainder := authorizer.PartiallyEvaluateConditionsAwareDecision(unevaluatedDecision, data, func(condition) Result {
     // best-effort try to evaluate conditions in-process for known types.
     // in reality, this would source in-process evaluators from some kind of shared registry
     if condition.Type != "cel" { return Unevaluatable() }
     result, err := celEnv.Evaluate(condition)
     // we cannot trust in-process errors to be "real errors", as there could be version skew between the CEL env of the API server and the authorizer (authorizer one is the one that matters)
     if err != nil { return Unevaluatable() }
     return result
   })
   // short-circuit, no need to do an expensive webhook if we could make do in-process
   if remainder.IsUnconditional() {
     return remainder
   }
   // non-trivial remainder, send webhook to the authorizer that authored it
   return doWebhookEvaluate(remainder, data)
}
